window.VAHINI_SATHYA_SAI_CH15_HI = "\"हिंदू धर्म विभिन्न देवताओं की पूजा की अनुमति देता है। इसके परिणामस्वरूप सांप्रदायिक झगड़े और गुट पैदा हुए हैं जो भूमि को भय और अशांति से भर देते हैं।\" देश में सभी अंतर्कलहों और आंदोलनों का कारण इस एक बुनियादी दोष का पता लगाया जा सकता है - यह कई पर्यवेक्षकों का बिना सोचे-समझे फैसला है। लेकिन ये फैसला सही नहीं है. यह कल्पना की एक कमज़ोर उड़ान है, जो तर्कशक्ति से रहित व्यक्तियों द्वारा की जाती है।\n\nपश्चिम में, सभी देशों के निवासी कमोबेश ईसाई धर्म के अनुयायी हैं। हालाँकि वे सभी एक ईश्वर की पूजा करते हैं, फिर भी वे जंगली जानवरों से भी कहीं अधिक भयानक तरीकों से एक-दूसरे का वध कर रहे हैं। क्या वे युद्ध नहीं छेड़ते हैं जिसमें निर्दोष महिलाओं, बच्चों और वृद्धों सहित संघर्ष स्थल से दूर के लोगों को निर्दयी अग्निशक्ति द्वारा पृथ्वी से मिटा दिया जाता है? क्या उनका धर्म ऐसे हृदयहीन, अपमानजनक, मूर्खतापूर्ण और राक्षसी विनाश और भ्रातृहत्या का मूल कारण है? निःसंदेह, वे एक ही धर्म के हैं और वे एक ईश्वर की पूजा करते हैं, लेकिन आराधना के मुखौटे के पीछे कोई जहरीला गुण छिपा होगा, जो पूरे व्यक्तित्व को प्रदूषित कर रहा है। गुटों, झगड़ों और युद्धों का रंचमात्र भी कारण धर्म नहीं हो सकता।\n\nजर्मनी में जाति समूहों और सांप्रदायिक झगड़ों के लिए कोई जगह नहीं थी। इसने विज्ञान और प्रौद्योगिकी में असाधारण प्रगति हासिल की थी। वह अपनी शक्ति, साहस और वीरता के बल पर राष्ट्रों की अग्रणी पंक्ति में चमका। ऐसे राष्ट्र को चार विजयी शक्तियों द्वारा चार टुकड़ों में विभाजित कर दिया गया था और प्रत्येक टुकड़े पर एक अलग राष्ट्र द्वारा शासन किया जा रहा था! जापान, जिसमें धार्मिक मतभेदों और सांप्रदायिक झगड़ों की कोई समस्या नहीं है, को कुछ वर्षों तक राष्ट्रों का प्रतिशोध झेलना पड़ा! कारण क्या था? राष्ट्रों के पतन का कारण केवल धर्म नहीं हो सकता।\n\nकोई ऐसे संसार की कल्पना भी नहीं कर सकता जिसमें मतभेद न हों। मतभेद बुद्धि के आंतरिक स्रोतों और प्रभावों के संचयी प्रभाव से पैदा होते हैं। प्रत्येक प्राणी का जीवन इसी बुद्धि और इसी प्रभाव की बाह्य अभिव्यक्ति है। जड़ और अक्रिय सत्ताएँ विभिन्न स्तरों पर इस बुद्धि की अभिव्यक्तियाँ हैं। तोता अपनी आँखें अलग तरह से घुमाता है। कौआ बिल्कुल अलग ढंग से वैसा ही करता है। सियार परिस्थितियों का कारण कुत्ते से अलग बताता है। पशुओं का स्वभाव एक प्रकार का होता है। मनुष्य का स्वभाव दूसरे प्रकार का है। मनुष्य और मनुष्य के बीच अर्जित ज्ञान में अंतर होता है। न केवल ज्ञान में बल्कि शारीरिक विशेषताओं और व्यक्तिगत आकर्षण में भी अनगिनत विविधताएँ हैं। उनकी पसंद-नापसंद, उनके विचार और भावनाएं उनके पास मौजूद ज्ञान और जिस पेशे से वे जुड़े हैं, उससे अलग-अलग तरीकों से आकार लेते हैं। हमें इतनी दूर जाने की कोई जरूरत नहीं है। यहां तक ​​कि एक ही गर्भ में एक साथ पल रहे जुड़वाँ बच्चे भी अक्सर एक जैसे नहीं होते हैं। वे भिन्न-भिन्न स्वभाव प्रकट करते हैं। इसका कारण क्या है? इसका कारण बुद्धि के विकास में अंतर है।\n\nअत: मानवजाति किसी भी समय मतभेदों से मुक्त नहीं हो सकती। सार्वभौमिक समानता एक असंभव आकांक्षा है. इसे धरती पर स्थापित करने की चाहत एक कल्पना है. यह आकाश में फूलों की तलाश है।\n\nजानवर इस बोध के साथ जीता है कि वह एक जानवर है, पक्षी को यह बोध रहता है कि वह एक पक्षी है। एक महिला खुद को दुनिया की गतिविधियों में व्यस्त रखती है, यह जानते हुए कि वह एक महिला है; मनुष्य भी ऐसा ही करता है। जब तक नींद हावी न हो जाए, व्यक्ति के पास जो चेतना होती है, वह नींद से जागने के बाद भी बिना किसी बदलाव के जारी रहती है। जीव सोने से पहले की तरह ही अपनी गतिविधियाँ जारी रखता है। मनुष्य अपनी गतिविधि वहीं जारी रखता है जहां उसकी गतिविधि नींद से टूट गई थी। इसी प्रकार, मनुष्य भी इस जीवन में, मृत्यु से टूटी हुई गतिविधियाँ, जहाँ वे समाप्त हुई थीं, जारी रखता है। \"यम, यम वापि स्मरं भावम्, त्यजत्यन्ते कालेबरम। वह अंत में अपने शरीर को त्याग देता है, उन भावनाओं को याद करते हुए जिन्होंने उसे इतनी दृढ़ता से प्रेरित किया।\" और गीता में, \"तम तमैवेति कौन्तेय, सदा तद् भाव भवितः - वह उस स्थिति को प्राप्त कर लेता है जिसकी ओर उसकी भावनाएँ हमेशा निर्देशित होती थीं।\" अगले जीवन की प्रकृति उन भावनाओं के अनुरूप होती है जो मनुष्य जब अपनी लाश त्यागता है तो उसके मन में व्याप्त हो जाती है। क्योंकि, वे भावनाएँ केवल उन भावनाओं के अनुरूप होंगी जिन्होंने उसके जीवन के दिनों को प्रेरित किया। गहराई से विचार करने पर यह स्पष्ट हो जायेगा कि मूल सत्य तो यही है कि सब कुछ बुद्धि के उच्चीकरण में प्राप्त प्रगति पर निर्भर है।\n\nयद्यपि बाहरी रूप में एक निश्चित एकरूपता दिखाई दे सकती है, आंतरिक प्रकृति में व्यापक और विविध अंतर मौजूद हैं। किसी वंश या प्रजाति का निर्णय मुख्यतः बाहरी विशेषताओं के आधार पर किया जाता है, जो वास्तव में आंतरिक बुद्धि की प्रकट अभिव्यक्तियाँ हैं। व्यक्ति मुख्यतः एक रूप है। मनुष्य, पेड़, पहाड़ी, गौरैया, लोमड़ी, कुत्ता, गाय, साँप, बिच्छू - ये \"ध्वनियाँ\" इन रूपों वाली प्रजातियों के सदस्यों को दर्शाती हैं। व्यक्तियों का विनाश हो सकता है, लेकिन प्रजातियाँ जारी रहेंगी। मनुष्य मर सकते हैं, लेकिन मानव जाति बनी रहेगी। पेड़ गिर सकते हैं और राख या धूल में बदल सकते हैं लेकिन प्रजाति कभी भी नष्ट नहीं हो सकती। जीव जाति शाश्वत है, पूर्ण विनाश कभी नहीं हो सकता।\n\nयदि हम अपने दैनिक जीवन में अनुभव होने वाली छोटी-छोटी चीजों का भी विश्लेषण और जांच करें, तो ये सत्य हमारे सामने स्पष्ट रूप से प्रकट होंगे। हम कहते हैं कि मानव प्रजाति में हर किसी में मानवीय विशेषताएं होती हैं लेकिन जब हम किसी एक व्यक्ति का मूल्यांकन करते हैं तो हम उसके गुणों और आदतों, वर्तमान स्थिति और भविष्य की संभावनाओं पर विशेष ध्यान देते हैं।\n\nगायें—ये सभी—एक ही प्रजाति की हैं। लेकिन जब हमें गाय खरीदने की इच्छा होती है तो हम उसके माता-पिता का पता लगाने की कोशिश करते हैं। हम शरीर पर शुभ निशान देखते हैं। इससे हमें भरपूर दूध मिलना चाहिए। यह अवश्य ही एक सुंदर, छोटा, शांत जानवर होगा। हम केवल इन वांछनीय गुणों वाली गायें ही खरीदते हैं। हम इस बात से आकर्षित नहीं हैं कि यह बाकी प्रजातियों की तरह गाय है. हम बांझ गाय या जंगली अनियंत्रित गाय नहीं खरीदते। इसलिए, यद्यपि सभी मनुष्य कमोबेश एक जैसे होते हैं, फिर भी किसी का मूल्यांकन उसके गुणों के आधार पर ही किया जाना चाहिए।\n\nजब किसी अन्य विषय पर गहराई से पूछताछ की जायेगी तो यह स्पष्ट हो जायेगा कि ऊँच-नीच का भेद भाव स्वाभाविक प्रतिक्रिया है। हालाँकि मूत्र और मल समान रूप से अशुद्ध हैं, गाय के मूत्र को पवित्र माना जाता है। पवित्रता का श्रेय अन्य जानवरों के मूत्र या मल को नहीं दिया जाता है; ये निश्चय ही अपवित्र हैं. अग्नि का उदाहरण लीजिए, अग्नि। अग्नि तो अग्नि है, चाहे रूप कोई भी हो। हम घर में दीपक जलाते हैं. हमारे चूल्हों में आग है. हमारे पास यज्ञ की अग्नि है, जिसकी लपटें उठ रही हैं। यह अग्नि पूजनीय और पूजित है; लोग इसके सामने साष्टांग झुकते हैं। लेकिन दीपक और चूल्हे की आग का इतना ऊँचा मूल्यांकन नहीं किया जाता। जब श्मशान भूमि पर किसी शव को जलाने के लिए आग जलाई जाती है, तो लौ किसी अन्य उपयोग के लिए पर्याप्त शुद्ध नहीं मानी जाती है। इस पर कोई भी रोटी नहीं पकाएगा; कोई भी इसका आदर नहीं करेगा या इसके सामने साष्टांग प्रणाम नहीं करेगा। क्योंकि, इसे \"नीचा,\" \"अपवित्र,\" \"प्रदूषित\" माना जाता है।\n\nइसी प्रकार, यद्यपि मनुष्यों का भौतिक रूप एक जैसा होता है, प्रत्येक शरीर की विशिष्टताएं और अन्य आवरण जिनमें वह घिरा हुआ है, और उसके गुणों और गतिविधियों की प्रकृति, उनके बीच अंतर करना आवश्यक है। कुछ को \"उच्च\" और कुछ को \"निम्न\" माना जाना चाहिए।\n\nसभी बिजली के बल्ब समान गुणवत्ता का प्रकाश उत्सर्जित नहीं करते हैं। कुछ उज्ज्वल हैं और कुछ नीरस हैं। प्रत्येक बल्ब में समान धारा होती है, हालांकि कुछ इसे पूरी ताकत से व्यक्त करते हैं और अन्य ऐसा करने में सक्षम नहीं होते हैं।\n\nहमें यह स्वीकार करना होगा कि दुनिया के विकास के लिए जागरूकता का स्तर, उत्कृष्टता के चरण, ऊंच-नीच, पवित्र और अपवित्र, धार्मिक और अधार्मिक जैसे भेद आवश्यक शर्तें हैं। वे अपरिहार्य हैं. वे ईश्वरीय इच्छा द्वारा डिज़ाइन किए गए हैं।";
